// 旁支真值、当时存在成年、真实本人声明与提交者身份分别核验，不因一项成立推其余授权。
#include "collateral_recognition_source.hpp"
#include "resident/domains/interaction/face_to_face_contact.hpp"
#include <charconv>
#include <tuple>
namespace hanmo::resident {namespace {
bool identity(const WorldIdentity& a,const WorldIdentity& b){return std::tie(a.world_id,a.execution_epoch,a.revision,a.tick)==std::tie(b.world_id,b.execution_epoch,b.revision,b.tick);}
bool context_equal(const InteractionContext& a,const InteractionContext& b){return std::tie(a.place_id,a.provider_actor_id,a.role_id,a.kind,a.encounter_id,a.input_error)==std::tie(b.place_id,b.provider_actor_id,b.role_id,b.kind,b.encounter_id,b.input_error);}
bool origin_equal(const KnownPersonalActorOrigin& a,const KnownPersonalActorOrigin& b){return std::tie(a.kind,a.actor_id,a.birth_fact_id,a.creation_fact_id,a.prototype_id)==std::tie(b.kind,b.actor_id,b.birth_fact_id,b.creation_fact_id,b.prototype_id);}
bool proof_equal(const KnownPersonalDialogueProof& a,const KnownPersonalDialogueProof& b){const auto& x=a.declaration.meeting;const auto& y=b.declaration.meeting;return a.opening_fact_id==b.opening_fact_id&&a.template_id==b.template_id&&a.declaration.speaker_actor_id==b.declaration.speaker_actor_id&&std::tie(x.actor_id,x.provider_actor_id,x.session_id,x.dialogue_id,x.node_id,x.node_kind)==std::tie(y.actor_id,y.provider_actor_id,y.session_id,y.dialogue_id,y.node_id,y.node_kind)&&identity(x.source_identity,y.source_identity)&&context_equal(x.context,y.context)&&origin_equal(a.listener_origin,b.listener_origin)&&origin_equal(a.provider_origin,b.provider_origin);}
bool reference(const StableId& id){return !id.empty()&&id.size()<=256;}
std::optional<Integer> instance(const CommonStore& c,const StableId& id,const StableId& prefix){const auto lead=prefix+":";if(id.rfind(lead,0)!=0)return {};const auto digits=id.substr(lead.size());Integer n=0;const auto p=std::from_chars(digits.data(),digits.data()+digits.size(),n);if(p.ec!=std::errc{}||p.ptr!=digits.data()+digits.size()||n<1||n>=c.state().next_instance_id||std::to_string(n)!=digits)return {};return n;}
bool selected(const KnownPersonalDialogueSelector& selector,const KnownPersonalActorOrigin& origin,const StableId& actor){if(origin.actor_id!=actor)return false;if(selector.kind=="installed_actor")return origin.kind=="installed_actor"&&selector.source_id==actor&&origin.birth_fact_id.empty()&&origin.creation_fact_id.empty()&&origin.prototype_id.empty();return selector.kind=="born_prototype"&&origin.kind=="recorded_birth"&&selector.source_id==origin.prototype_id&&reference(origin.birth_fact_id)&&origin.creation_fact_id==actor;}
Status bound(const CollateralRecognitionContext& x,const CollateralRecognitionSource& s,const StableId& before){
    const auto& common=x.people.common;auto valid=validate_collateral_control_catalog(x.catalog,x.original_requests,x.interactions,x.templates);if(!valid.ok)return valid;if(x.interactions.common.get()!=&x.people.catalog||!x.meetings)return common_failure("CollateralRecognitionCandidateRequired");const auto* d=x.catalog.definitions.find(s.request_id);if(!d||s.terms_version!=d->terms_version||s.first_actor_id==s.second_actor_id||!reference(s.first_actor_id)||!reference(s.second_actor_id)||s.world_id!=common.state().identity.world_id||std::all_of(s.world_id.begin(),s.world_id.end(),[](auto b){return b==0;})||s.scenario_id!=common.state().metadata.scenario_id||s.tick<0||s.tick>common.tick()||s.revision<0||s.revision>common.revision())return common_failure("CollateralRecognitionSourceMismatch");
    const auto& proof=s.statement;const auto& m=proof.declaration.meeting;auto t=x.templates(d->template_id);if(!t.ok)return {false,{},t.error};
    if(!reference(proof.opening_fact_id)||proof.template_id!=d->template_id||proof.declaration.speaker_actor_id!=s.second_actor_id||m.actor_id!=s.first_actor_id||m.provider_actor_id!=s.second_actor_id||!reference(m.session_id)||m.dialogue_id!=t.value.dialogue_id||m.node_id!=d->recognize_node_id||m.node_kind!="say"||m.source_identity.world_id!=s.world_id||m.source_identity.execution_epoch<1||m.source_identity.revision!=s.revision||m.source_identity.tick!=s.tick||!face_to_face_contact_context_valid(m.context)||m.context.kind!=std::optional<StableId>{"narrative"}||!m.context.role_id.empty()||m.context.provider_actor_id!=s.second_actor_id||!selected(t.value.listener,proof.listener_origin,s.first_actor_id)||!selected(t.value.provider,proof.provider_origin,s.second_actor_id)||s.ancestry.first_actor_id!=s.first_actor_id||s.ancestry.second_actor_id!=s.second_actor_id)return common_failure("CollateralRecognitionStatementMismatch");
    const auto opened=instance(common,proof.opening_fact_id,known_personal_dialogue_opened_kind);const auto* opening=common.state().facts.find(proof.opening_fact_id);if(!opened||!opening||opening->id!=proof.opening_fact_id||opening->kind!=known_personal_dialogue_opened_kind||opening->domain!=known_personal_dialogue_module)return common_failure("CollateralRecognitionOpeningRequired");if(!before.empty()){const auto decision=instance(common,before,"family_collateral");const auto& order=common.state().facts.order();const auto i=std::find(order.begin(),order.end(),proof.opening_fact_id),j=std::find(order.begin(),order.end(),before);if(!decision||*opened>=*decision||i==order.end()||j==order.end()||i>=j)return common_failure("CollateralRecognitionOpeningBoundaryMismatch");}
    for(const auto& actor:{std::make_pair(s.first_actor_id,s.first_birth_tick),std::make_pair(s.second_actor_id,s.second_birth_tick)}){auto present=before.empty()?read_actor_presence(common,x.people.catalog,x.people.death_origin,actor.first):read_actor_presence_before_fact(common,x.people.catalog,x.people.death_origin,actor.first,s.tick,before);if(!present.ok)return {false,{},present.error};if(!present.value.alive)return common_failure("CollateralRecognitionLivingPartiesRequired",actor.first);auto age=x.people.births?(before.empty()?read_actor_age(common,x.people.catalog,*x.people.births,actor.first):read_actor_age_before_fact(common,x.people.catalog,*x.people.births,actor.first,s.tick,before)):(before.empty()?read_actor_age(common,x.people.catalog,actor.first):read_actor_age_before_fact(common,x.people.catalog,actor.first,s.tick,before));if(!age.ok)return {false,{},age.error};if(!age.value.adult||age.value.birth_tick!=actor.second)return common_failure("CollateralRecognitionAdultSourceRequired",actor.first);}
    return common_success();
}
bool recognition_boundary(const CommonStore& c,const StableId& id){const StableId prefix="family_collateral:";if(id.rfind(prefix,0)!=0)return false;const auto digits=id.substr(prefix.size());Integer n=0;auto read=std::from_chars(digits.data(),digits.data()+digits.size(),n);const auto* h=c.state().facts.find(id);return read.ec==std::errc{}&&read.ptr==digits.data()+digits.size()&&n>0&&n<c.state().next_instance_id&&std::to_string(n)==digits&&h&&h->id==id&&h->kind=="family_collateral_recognized"&&h->domain=="family_collateral_legacy";}
}
Outcome<CollateralRecognitionSource> preview_collateral_recognition(const CollateralRecognitionContext& x,const StableId& first,const StableId& second,const StableId& request){auto valid=validate_collateral_control_catalog(x.catalog,x.original_requests,x.interactions,x.templates);if(!valid.ok)return {false,{},valid.error};const auto& c=x.people.common;const auto* d=x.catalog.definitions.find(request);if(!d||!x.meetings||first!=c.state().metadata.player_actor_id)return {false,{},common_failure("CollateralRecognitionCurrentPlayerRequired").error};auto proof=x.meetings->known_personal_dialogue(first,second,d->template_id);if(!proof.ok)return {false,{},proof.error};if(!identity(proof.value.declaration.meeting.source_identity,c.state().identity))return {false,{},common_failure("StaleCollateralRecognitionMeeting").error};auto ancestry=make_collateral_family_origin(x.people,first,second);if(!ancestry.ok)return {false,{},ancestry.error};CollateralRecognitionSource s;s.request_id=request;s.first_actor_id=first;s.second_actor_id=second;s.scenario_id=c.state().metadata.scenario_id;s.world_id=c.state().identity.world_id;s.terms_version=d->terms_version;s.tick=c.tick();s.revision=c.revision();s.ancestry=std::move(ancestry.value);s.statement=std::move(proof.value);auto a=x.people.births?read_actor_age(c,x.people.catalog,*x.people.births,first):read_actor_age(c,x.people.catalog,first);if(!a.ok)return {false,{},a.error};auto b=x.people.births?read_actor_age(c,x.people.catalog,*x.people.births,second):read_actor_age(c,x.people.catalog,second);if(!b.ok)return {false,{},b.error};s.first_birth_tick=a.value.birth_tick;s.second_birth_tick=b.value.birth_tick;valid=bound(x,s,{});return valid.ok?Outcome<CollateralRecognitionSource>{true,std::move(s),{}}:Outcome<CollateralRecognitionSource>{false,{},valid.error};}
Status revalidate_collateral_recognition(const CollateralRecognitionContext& x,const CollateralRecognitionSource& source){auto fresh=preview_collateral_recognition(x,source.first_actor_id,source.second_actor_id,source.request_id);if(!fresh.ok)return {false,{},fresh.error};return collateral_recognition_source_equal(source,fresh.value)?common_success():common_failure("StaleCollateralRecognitionSource");}
Status validate_collateral_recognition_source_before_fact(const CollateralRecognitionContext& x,const CollateralRecognitionSource& source,const StableId& fact){if(!recognition_boundary(x.people.common,fact))return common_failure("CollateralRecognitionActualFactRequired",fact);auto valid=bound(x,source,fact);if(!valid.ok)return valid;if(!x.player_before)return common_failure("CollateralRecognitionPlayerHistoryRequired",fact);auto player=x.player_before(source.tick,fact);if(!player.ok)return {false,{},player.error};if(player.value!=source.first_actor_id)return common_failure("CollateralRecognitionHistoricalPlayerMismatch",fact);valid=validate_collateral_family_origin_before_fact(x.people,source.ancestry,source.tick,fact);if(!valid.ok)return valid;return x.meetings->known_personal_dialogue_before_fact(source.statement,source.tick,fact);}
bool collateral_recognition_source_equal(const CollateralRecognitionSource& a,const CollateralRecognitionSource& b){return std::tie(a.request_id,a.first_actor_id,a.second_actor_id,a.scenario_id,a.world_id,a.terms_version,a.tick,a.revision,a.first_birth_tick,a.second_birth_tick)==std::tie(b.request_id,b.first_actor_id,b.second_actor_id,b.scenario_id,b.world_id,b.terms_version,b.tick,b.revision,b.first_birth_tick,b.second_birth_tick)&&collateral_family_origin_equal(a.ancestry,b.ancestry)&&proof_equal(a.statement,b.statement);}
}
